import subprocess, os, struct, time
EXE=os.path.abspath("./executable")
def run(*args, env_extra=None, cwd=None):
    env=os.environ.copy()
    if env_extra: env.update(env_extra)
    return subprocess.run([EXE]+list(args), capture_output=True, text=True, env=env, cwd=cwd)
import tempfile
def fresh():
    d=tempfile.mkdtemp(); env={"_ZO_DATA_DIR": d}
    def z(*a, extra=None, cwd=None):
        e=dict(env)
        if extra: e.update(extra)
        return run(*a, env_extra=e, cwd=cwd)
    return d, z
def write_db(d, entries):
    import struct
    with open(os.path.join(d,"db.zo"),"wb") as f:
        f.write(struct.pack('<I', 3))
        f.write(struct.pack('<Q', len(entries)))
        for p, rank, ts in entries:
            b=p.encode()
            f.write(struct.pack('<Q', len(b)))
            f.write(b)
            f.write(struct.pack('<d', rank))
            f.write(struct.pack('<Q', ts))

now=int(time.time())
# boundary tests
for delta, label in [(3599,"just under 1h"),(3600,"exactly 1h"),(3601,"just over 1h"),(86399,"under 1d"),(86400,"exactly 1d"),(86401,"over 1d"),(7*86400-1,"under 1w"),(7*86400,"exactly 1w"),(7*86400+1,"over 1w")]:
    d,z=fresh()
    os.makedirs("/tmp/bound", exist_ok=True)
    write_db(d, [("/tmp/bound", 4.0, now-delta)])
    out=z("query","--list","--score").stdout.strip()
    print(f"{label} delta={delta}: {out!r}")
PY
"}

