{"command": "python3 <<'PY'
def jaro(s1,s2):
    if s1==s2: return 1.0
    len1,len2=len(s1),len(s2)
    if len1==0 or len2==0: return 0.0
    match_dist=max(len1,len2)//2-1
    s1m=[False]*len1
    s2m=[False]*len2
    m=0
    for i in range(len1):
        lo=max(0,i-match_dist)
        hi=min(i+match_dist+1,len2)
        for j in range(lo,hi):
            if not s2m[j] and s1[i]==s2[j]:
                s1m[i]=True; s2m[j]=True; m+=1; break
    if m==0: return 0.0
    t=0; k=0
    for i in range(len1):
        if s1m[i]:
            while not s2m[k]: k+=1
            if s1[i]!=s2[k]: t+=1
            k+=1
    t//=2
    j=(m/len1 + m/len2 + (m-t)/m)/3.0
    prefix=0
    for i in range(min(4,min(len1,len2))):
        if s1[i]==s2[i]: prefix+=1
        else: break
    return j + prefix*0.1*(1-j)

known_init=["--no-cmd","--cmd","--hook","--help","--version"]
for unk in ["--hk","--hok","--hoo","--ho"]:
    print(f"\nunk {unk}:")
    for k in known_init:
        print(f"  {k}: {jaro(unk,k):.4f}  stripped:{jaro(unk[2:],k[2:]):.4f}")
